CREATE TABLE public.responders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id), code text NOT NULL UNIQUE, kind text NOT NULL, name text NOT NULL, phone text NOT NULL, area text NOT NULL DEFAULT '', fixed boolean NOT NULL DEFAULT false, lat double precision, lng double precision, online boolean NOT NULL DEFAULT false, location_at timestamptz, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.responders TO authenticated; GRANT ALL ON public.responders TO service_role;
ALTER TABLE public.responders ENABLE ROW LEVEL SECURITY;
CREATE POLICY responders_read ON public.responders FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY responders_admin ON public.responders FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), victim text NOT NULL, phone text NOT NULL, area text NOT NULL DEFAULT '', lat double precision, lng double precision, accuracy double precision, location_at timestamptz, camera text NOT NULL DEFAULT 'back', status text NOT NULL DEFAULT 'active', outcome text, emergency_name text, emergency_phone text, sms_status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz);
GRANT SELECT ON public.incidents TO authenticated; GRANT ALL ON public.incidents TO service_role;
ALTER TABLE public.incidents ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX incidents_one_active_per_user ON public.incidents(user_id) WHERE status='active';
CREATE TABLE public.dispatch_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES public.incidents(id), responder_id uuid NOT NULL REFERENCES public.responders(id), state text NOT NULL DEFAULT 'alerted', distance_km double precision NOT NULL, arrived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(incident_id,responder_id));
GRANT SELECT ON public.dispatch_assignments TO authenticated; GRANT ALL ON public.dispatch_assignments TO service_role;
ALTER TABLE public.dispatch_assignments ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_access_incident(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT public.has_role(auth.uid(),'admin') OR EXISTS (SELECT 1 FROM public.incidents i WHERE i.id=_id AND i.user_id=auth.uid()) OR EXISTS (SELECT 1 FROM public.dispatch_assignments a JOIN public.responders r ON r.id=a.responder_id WHERE a.incident_id=_id AND r.user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.can_access_incident(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_access_incident(uuid) TO authenticated,service_role;
CREATE POLICY incidents_read ON public.incidents FOR SELECT TO authenticated USING (public.can_access_incident(id));
CREATE POLICY assignments_read ON public.dispatch_assignments FOR SELECT TO authenticated USING (public.can_access_incident(incident_id));
CREATE POLICY assigned_units_read ON public.responders FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.dispatch_assignments a WHERE a.responder_id=responders.id AND public.can_access_incident(a.incident_id)));
CREATE TABLE public.incident_locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES public.incidents(id), lat double precision NOT NULL, lng double precision NOT NULL, accuracy double precision, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.incident_locations TO authenticated; GRANT ALL ON public.incident_locations TO service_role;
ALTER TABLE public.incident_locations ENABLE ROW LEVEL SECURITY;
CREATE POLICY locations_read ON public.incident_locations FOR SELECT TO authenticated USING (public.can_access_incident(incident_id));
CREATE TABLE public.incident_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES public.incidents(id), actor_id uuid, event text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.incident_events TO authenticated; GRANT ALL ON public.incident_events TO service_role;
ALTER TABLE public.incident_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY events_read ON public.incident_events FOR SELECT TO authenticated USING (public.can_access_incident(incident_id));
CREATE TABLE public.live_records (id text NOT NULL, collection text NOT NULL, content jsonb NOT NULL, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(collection,id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.live_records TO authenticated; GRANT SELECT ON public.live_records TO anon; GRANT ALL ON public.live_records TO service_role;
ALTER TABLE public.live_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY records_public ON public.live_records FOR SELECT TO anon,authenticated USING (published AND collection IN ('website','posts','zones'));
CREATE POLICY records_admin ON public.live_records FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.kyc_submissions (user_id uuid PRIMARY KEY REFERENCES public.profiles(id), dob date NOT NULL, birth_reg text, guardian jsonb, documents jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.kyc_submissions TO authenticated; GRANT ALL ON public.kyc_submissions TO service_role;
ALTER TABLE public.kyc_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY kyc_read ON public.kyc_submissions FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.user_security (user_id uuid PRIMARY KEY REFERENCES public.profiles(id), pin_hash text NOT NULL, attempts integer NOT NULL DEFAULT 0, locked_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.user_security TO service_role;
ALTER TABLE public.user_security ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.incident_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid NOT NULL REFERENCES public.incidents(id), storage_path text NOT NULL, camera text NOT NULL, captured_at timestamptz NOT NULL, responder_id uuid NOT NULL, responder_name text NOT NULL, tags text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.incident_evidence TO authenticated; GRANT ALL ON public.incident_evidence TO service_role;
ALTER TABLE public.incident_evidence ENABLE ROW LEVEL SECURITY;
CREATE POLICY evidence_read ON public.incident_evidence FOR SELECT TO authenticated USING (public.can_access_incident(incident_id));
CREATE TABLE public.public_submission_limits (fingerprint text PRIMARY KEY, submitted_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.public_submission_limits TO service_role;
ALTER TABLE public.public_submission_limits ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS dob date, ADD COLUMN IF NOT EXISTS emergency_relation text, ADD COLUMN IF NOT EXISTS false_count integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS last_lat double precision, ADD COLUMN IF NOT EXISTS last_lng double precision;
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
CREATE FUNCTION public.protect_profile_controls() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF current_user NOT IN ('postgres','service_role','supabase_admin') AND NOT public.has_role(auth.uid(),'admin') AND (NEW.kyc_status IS DISTINCT FROM OLD.kyc_status OR NEW.account_status IS DISTINCT FROM OLD.account_status OR NEW.status_reason IS DISTINCT FROM OLD.status_reason OR NEW.false_count IS DISTINCT FROM OLD.false_count OR NEW.phone IS DISTINCT FROM OLD.phone) THEN RAISE EXCEPTION 'Account controls require an administrator'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_profile_controls BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_profile_controls();
CREATE FUNCTION public.validate_incident_transition() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF NEW.status NOT IN ('active','cancelled','rescued','closed') THEN RAISE EXCEPTION 'Invalid incident status'; END IF; IF TG_OP='UPDATE' AND OLD.status<>'active' AND NEW.status IS DISTINCT FROM OLD.status THEN RAISE EXCEPTION 'Incident already ended'; END IF; IF NEW.status='rescued' AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Only administrators can confirm rescue'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_incident_transition BEFORE INSERT OR UPDATE ON public.incidents FOR EACH ROW EXECUTE FUNCTION public.validate_incident_transition();
CREATE FUNCTION public.start_incident(_lat double precision,_lng double precision,_accuracy double precision DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE p public.profiles; result uuid; BEGIN SELECT * INTO p FROM public.profiles WHERE id=auth.uid() FOR UPDATE; IF p.id IS NULL OR p.account_status<>'active' OR p.kyc_status<>'approved' THEN RAISE EXCEPTION 'Active approved account required'; END IF; IF _lat NOT BETWEEN -90 AND 90 OR _lng NOT BETWEEN -180 AND 180 OR _lat IS NULL OR _lng IS NULL THEN RAISE EXCEPTION 'Valid location required'; END IF; SELECT id INTO result FROM public.incidents WHERE user_id=p.id AND status='active'; IF result IS NOT NULL THEN RETURN result; END IF; INSERT INTO public.incidents(user_id,victim,phone,lat,lng,accuracy,location_at,emergency_name,emergency_phone) VALUES(p.id,p.full_name,coalesce(p.phone,''),_lat,_lng,_accuracy,now(),p.emergency_contact_name,p.emergency_contact_phone) RETURNING id INTO result; INSERT INTO public.dispatch_assignments(incident_id,responder_id,state,distance_km) SELECT result,q.id,CASE WHEN q.kind IN ('patrol','fari','station') THEN 'accepted' ELSE 'alerted' END,q.dist FROM (SELECT r.id,r.kind,6371*2*asin(sqrt(least(1.0,power(sin(radians(r.lat-_lat)/2),2)+cos(radians(_lat))*cos(radians(r.lat))*power(sin(radians(r.lng-_lng)/2),2)))) AS dist,row_number() OVER (PARTITION BY CASE WHEN r.kind IN ('volunteer','officer') THEN 'personal' ELSE r.kind END ORDER BY power(r.lat-_lat,2)+power((r.lng-_lng)*cos(radians(_lat)),2)) AS rank FROM public.responders r JOIN public.profiles rp ON rp.id=r.user_id WHERE r.online AND rp.account_status='active' AND r.lat IS NOT NULL AND r.lng IS NOT NULL AND (r.fixed OR r.location_at>now()-interval '2 minutes')) q WHERE q.rank<=CASE q.kind WHEN 'patrol' THEN 2 WHEN 'fari' THEN 1 WHEN 'station' THEN 1 ELSE 10 END; INSERT INTO public.incident_events(incident_id,actor_id,event) VALUES(result,p.id,'started'); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.start_incident(double precision,double precision,double precision) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.start_incident(double precision,double precision,double precision) TO authenticated;
CREATE FUNCTION public.complete_incident(_id uuid,_status text,_outcome text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') OR _status NOT IN ('rescued','closed') THEN RAISE EXCEPTION 'Administrator required'; END IF; UPDATE public.incidents SET status=_status,outcome=_outcome,ended_at=now(),updated_at=now() WHERE id=_id AND status='active'; IF NOT FOUND THEN RAISE EXCEPTION 'Active incident not found'; END IF; INSERT INTO public.incident_events(incident_id,actor_id,event) VALUES(_id,auth.uid(),_status); END $$;
REVOKE ALL ON FUNCTION public.complete_incident(uuid,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.complete_incident(uuid,text,text) TO authenticated;
CREATE INDEX assignments_incident_idx ON public.dispatch_assignments(incident_id); CREATE INDEX locations_incident_idx ON public.incident_locations(incident_id,created_at); CREATE INDEX evidence_incident_idx ON public.incident_evidence(incident_id);
CREATE TRIGGER responders_updated BEFORE UPDATE ON public.responders FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column(); CREATE TRIGGER incidents_updated BEFORE UPDATE ON public.incidents FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column(); CREATE TRIGGER records_updated BEFORE UPDATE ON public.live_records FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column(); CREATE TRIGGER kyc_updated BEFORE UPDATE ON public.kyc_submissions FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column(); CREATE TRIGGER evidence_updated BEFORE UPDATE ON public.incident_evidence FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
ALTER PUBLICATION supabase_realtime ADD TABLE public.incidents,public.dispatch_assignments,public.responders,public.live_records,public.incident_evidence;